import { test, expect } from '@playwright/test';

test.describe('Mobile Touch Target Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/mobile-app');
  });

  test('should have large enough touch targets for easy tapping on mobile devices', async ({ page }) => {
    // Set viewport to mobile dimensions
    await page.setViewportSize({ width: 375, height: 667 });

    // Verify touch targets are visible and large enough
    const button = page.getByRole('button', { name: /submit/i });
    await expect(button).toBeVisible();
    await expect(button).toHaveAttribute('aria-label', 'Submit form');

    const input = page.getByLabel(/email/i);
    await expect(input).toBeVisible();
    await expect(input).toHaveAttribute('aria-label', 'Email address');

    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();
    await expect(submitButton).toHaveAttribute('aria-label', 'Submit form');

    // Verify touch target size using getBoundingClientRect
    const buttonRect = await button.boundingBox();
    expect(buttonRect.width).toBeGreaterThan(44);
    expect(buttonRect.height).toBeGreaterThan(44);

    const inputRect = await input.boundingBox();
    expect(inputRect.width).toBeGreaterThan(44);
    expect(inputRect.height).toBeGreaterThan(44);

    // Verify touch target is not too close to edge
    const buttonEdge = buttonRect.left;
    const buttonEdgeRight = buttonRect.right;
    const inputEdge = inputRect.left;
    const inputEdgeRight = inputRect.right;

    expect(buttonEdge).toBeGreaterThan(0);
    expect(buttonEdgeRight).toBeLessThan(page.viewport().width);
    expect(inputEdge).toBeGreaterThan(0);
    expect(inputEdgeRight).toBeLessThan(page.viewport().width);

    // Verify touch targets have sufficient padding
    const buttonPadding = buttonRect.width - buttonRect.width / 2;
    const inputPadding = inputRect.width - inputRect.width / 2;
    expect(buttonPadding).toBeGreaterThan(10);
    expect(inputPadding).toBeGreaterThan(10);

    // Verify touch targets have sufficient margin
    const buttonMargin = buttonRect.top - buttonRect.height / 2;
    const inputMargin = inputRect.top - inputRect.height / 2;
    expect(buttonMargin).toBeGreaterThan(10);
    expect(inputMargin).toBeGreaterThan(10);

    // Verify touch targets are not overlapping
    const buttonOverlap = buttonRect.bottom - buttonRect.height / 2;
    const inputOverlap = inputRect.bottom - inputRect.height / 2;
    expect(buttonOverlap).toBeLessThan(inputRect.top);
    expect(inputOverlap).toBeLessThan(buttonRect.top);

    // Verify touch targets are not too close to each other
    const buttonToInputDistance = buttonRect.right - inputRect.left;
    expect(buttonToInputDistance).toBeGreaterThan(10);

    // Verify touch targets are accessible by keyboard
    const buttonKeyboardAccessible = await button.isKeyboardFocused();
    const inputKeyboardAccessible = await input.isKeyboardFocused();
    expect(buttonKeyboardAccessible).toBe(true);
    expect(inputKeyboardAccessible).toBe(true);

    // Verify error state is visible and accessible
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toHaveAttribute('aria-live', 'polite');
  });

  test('should handle touch targets with complex layouts and nested elements', async ({ page }) => {
    // Set viewport to mobile dimensions
    await page.setViewportSize({ width: 375, height: 667 });

    // Navigate to complex form page
    await page.goto('/complex-form');

    // Verify nested touch targets are accessible
    const nestedInput = page.getByLabel(/nested email/i);
    await expect(nestedInput).toBeVisible();
    await expect(nestedInput).toHaveAttribute('aria-label', 'Nested email address');

    const nestedSubmitButton = page.getByRole('button', { name: /submit/i });
    await expect(nestedSubmitButton).toBeVisible();
    await expect(nestedSubmitButton).toHaveAttribute('aria-label', 'Submit form with nested fields');

    // Verify nested touch targets have sufficient padding and margin
    const nestedInputRect = await nestedInput.boundingBox();
    const nestedInputPadding = nestedInputRect.width - nestedInputRect.width / 2;
    const nestedInputMargin = nestedInputRect.top - nestedInputRect.height / 2;
    expect(nestedInputPadding).toBeGreaterThan(10);
    expect(nestedInputMargin).toBeGreaterThan(10);

    // Verify nested touch targets are not overlapping
    const nestedButtonRect = await nestedSubmitButton.boundingBox();
    const nestedButtonOverlap = nestedButtonRect.bottom - nestedButtonRect.height / 2;
    const nestedInputOverlap = nestedInputRect.bottom - nestedInputRect.height / 2;
    expect(nestedButtonOverlap).toBeLessThan(nestedInputRect.top);
    expect(nestedInputOverlap).toBeLessThan(nestedButtonRect.top);

    // Verify nested touch targets are not too close to each other
    const nestedButtonToInputDistance = nestedButtonRect.right - nestedInputRect.left;
    expect(nestedButtonToInputDistance).toBeGreaterThan(10);

    // Verify nested touch targets are accessible by keyboard
    const nestedButtonKeyboardAccessible = await nestedSubmitButton.isKeyboardFocused();
    const nestedInputKeyboardAccessible = await nestedInput.isKeyboardFocused();
    expect(nestedButtonKeyboardAccessible).toBe(true);
    expect(nestedInputKeyboardAccessible).toBe(true);

    // Verify error state is visible and accessible for nested form
    const nestedErrorMessage = page.getByText(/nested error/i);
    await expect(nestedErrorMessage).toBeVisible();
    await expect(nestedErrorMessage).toHaveAttribute('aria-live', 'polite');

    // Verify error message is visible when nested input is invalid
    await nestedInput.fill('invalid-email');
    await expect(nestedErrorMessage).toBeVisible();
  });
});
